parameters.jsonBody:
={
  "model": "qwen2.5:7b",
  "stream": false,
  "prompt": "You are a sales development rep for a digital agency called Nivy International (services: SEO, AI Automation, VA, Design, Video). Write a personalized first-touch outreach for this lead.

Name: {{$json.name}}
Company: {{$json.company}}
Service interest: {{$json.service_type}}
What they said: {{($json.intent_summary || '').replace(/"/g, '\"').slice(0,500)}}

Return ONLY a valid JSON object with exactly these keys, no other text: email_subject (under 60 chars), email_body (120-180 words, friendly, ends with a clear call to book a call, plain text no markdown), linkedin_message (under 300 chars, casual, no hard sell), whatsapp_message (under 300 chars, casual, friendly opener)."
}

parameters.jsCode:
const response = $input.item.json.response || '';
let parsed = {};
try {
  parsed = JSON.parse(response);
} catch (e) {
  const match = response.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { email_subject: '', email_body: '', linkedin_message: '', whatsapp_message: '' };
}
const lead = $('Fetch Lead Detail').item.json;
return [{
  json: {
    odoo_lead_id: lead.odoo_lead_id,
    name: lead.name,
    email: lead.email,
    phone: lead.phone,
    company: lead.company,
    email_subject: parsed.email_subject || 'Following up on your enquiry',
    email_body: parsed.email_body || '',
    linkedin_message: parsed.linkedin_message || '',
    whatsapp_message: parsed.whatsapp_message || ''
  }
}];

parameters.query:
UPDATE clients_master
SET status = 'Replied', updated_at = now()
WHERE email = {{JSON.stringify($json.body.mail_from || $json.body.from)}}
RETURNING odoo_lead_id, name;

